  diag.append(dict(case=i,windows=windows,released=r['final_released'],release_s=r['settle_release_s'],max_quiet=r['max_consecutive_quiet_ticks'],final_hold_s=r['final_hold_s'],max_legal_normal_bw=float(load['legal_seat_normal_bw'][:,i].max()),integral_max_abs=max(abs(x['integral_rad']) for x in q),accepted_ticks=sum(x['integral_accepted'] for x in q),antiwindup_ticks=sum(x['integral_antiwindup'] for x in q)))
