 ev=[[r['case'],e['event'],fmt(e['time_s']),fmt(e['saved_sample_s']),e['geometry_available'],fmt(e['geometry_age_s']),fmt(e['height_error_mm']),fmt(e['slope_error_deg'])] for r in d['rows'] for e in r['geometry_before_events']]
